import Foundation

let filePath = "<tmp>"

let content = try! String(contentsOfFile: filePath, encoding: .utf8)
let lines = content.components(separatedBy: "\n").map { $0.replacingOccurrences(of: "\r", with: "") }.filter { !$0.trimmingCharacters(in: .whitespaces).isEmpty }

let dataLines = Array(lines.dropFirst())

struct Employee {
    let name: String
    let department: String
    let salary: Double
}

var employees: [Employee] = []

for line in dataLines {
    let fields = line.components(separatedBy: ",")
    guard fields.count >= 6 else { continue }
    let salary = Double(fields[3].trimmingCharacters(in: .whitespaces)) ?? 0
    let emp = Employee(
        name: fields[1].trimmingCharacters(in: .whitespaces),
        department: fields[2].trimmingCharacters(in: .whitespaces),
        salary: salary
    )
    employees.append(emp)
}

func formatInt(_ value: Double) -> String {
    let f = NumberFormatter()
    f.locale = Locale(identifier: "en_US")
    f.numberStyle = .decimal
    f.maximumFractionDigits = 0
    f.minimumFractionDigits = 0
    return f.string(from: NSNumber(value: value)) ?? "0"
}

func formatDec(_ value: Double) -> String {
    let f = NumberFormatter()
    f.locale = Locale(identifier: "en_US")
    f.numberStyle = .decimal
    f.maximumFractionDigits = 2
    f.minimumFractionDigits = 2
    return f.string(from: NSNumber(value: value)) ?? "0"
}

var deptSalaries: [String: [Double]] = [:]
for emp in employees {
    deptSalaries[emp.department, default: []].append(emp.salary)
}

let sortedDepts = deptSalaries.keys.sorted()

print("=== Salary Report ===")
print()
print("Average Salary by Department:")
for dept in sortedDepts {
    let salaries = deptSalaries[dept]!
    let avg = salaries.reduce(0, +) / Double(salaries.count)
    print("  \(dept): $\(formatDec(avg))")
}

print()

let highestEmp = employees.max(by: { $0.salary < $1.salary })!
print("Highest Paid: \(highestEmp.name) ($\(formatInt(highestEmp.salary)))")

print()

var deptCounts: [String: Int] = [:]
for emp in employees {
    deptCounts[emp.department, default: 0] += 1
}

let deptsWithMoreThan2 = deptCounts.filter { $0.value > 2 }.keys.sorted()
print("Departments with >2 employees:")
for dept in deptsWithMoreThan2 {
    print("  \(dept) (\(deptCounts[dept]!) employees)")
}

print()

let totalBudget = employees.reduce(0.0) { $0 + $1.salary }
print("Total Budget: $\(formatInt(totalBudget))")

