import java.io.*;
import java.util.*;
import java.util.regex.*;

public class Main {
    public static void main(String[] args) throws Exception {
        String filePath = "<tmp>";

        List<String> lines = new ArrayList<>();
        try (BufferedReader br = new BufferedReader(new FileReader(filePath))) {
            String line;
            while ((line = br.readLine()) != null) {
                if (!line.trim().isEmpty()) {
                    lines.add(line);
                }
            }
        }

        Pattern pattern = Pattern.compile("^\\[(\\d{4}-\\d{2}-\\d{2} (\\d{2}):\\d{2}:\\d{2})\\] (\\S+) \\(([^)]+)\\) - (.+)$");

        Map<String, Integer> levelCounts = new TreeMap<>();
        Map<String, Integer> componentErrors = new HashMap<>();
        Set<String> errorMessages = new TreeSet<>();
        Map<String, Integer> hourCounts = new HashMap<>();

        for (String line : lines) {
            Matcher m = pattern.matcher(line);
            if (m.matches()) {
                String hour = m.group(2);
                String level = m.group(3);
                String component = m.group(4);
                String message = m.group(5);

                levelCounts.merge(level, 1, Integer::sum);
                hourCounts.merge(hour, 1, Integer::sum);

                if (level.equals("ERROR")) {
                    componentErrors.merge(component, 1, Integer::sum);
                    errorMessages.add(message);
                }
            }
        }

        String topComponent = "";
        int topErrors = 0;
        for (Map.Entry<String, Integer> entry : componentErrors.entrySet()) {
            if (entry.getValue() > topErrors || (entry.getValue() == topErrors && entry.getKey().compareTo(topComponent) < 0)) {
                topErrors = entry.getValue();
                topComponent = entry.getKey();
            }
        }

        String busiestHour = "00";
        int busiestCount = 0;
        for (Map.Entry<String, Integer> entry : hourCounts.entrySet()) {
            if (entry.getValue() > busiestCount || (entry.getValue() == busiestCount && entry.getKey().compareTo(busiestHour) < 0)) {
                busiestCount = entry.getValue();
                busiestHour = entry.getKey();
            }
        }

        System.out.println("=== Log Analysis ===");
        System.out.println();
        System.out.println("Entries by Level:");
        for (Map.Entry<String, Integer> entry : levelCounts.entrySet()) {
            System.out.println("  " + entry.getKey() + ": " + entry.getValue());
        }
        System.out.println();
        System.out.println("Component with Most Errors: " + topComponent + " (" + topErrors + " errors)");
        System.out.println();
        System.out.println("Unique Error Messages:");
        for (String msg : errorMessages) {
            System.out.println("  - " + msg);
        }
        System.out.println();
        System.out.println("Busiest Hour: " + busiestHour + ":00 (" + busiestCount + " entries)");
    }
}

