import Foundation

let filePath = "<tmp>"

let content = try! String(contentsOfFile: filePath, encoding: .utf8)
let lines = content.components(separatedBy: "\n").filter { !$0.trimmingCharacters(in: .whitespaces).isEmpty }

var levelCounts: [String: Int] = [:]
var componentErrors: [String: Int] = [:]
var errorMessages: Set<String> = []
var hourCounts: [Int: Int] = [:]

for line in lines {
    let trimmed = line.trimmingCharacters(in: .whitespaces)
    guard trimmed.hasPrefix("[") else { continue }
    guard let closeBracket = trimmed.firstIndex(of: "]") else { continue }

    let timestamp = String(trimmed[trimmed.index(after: trimmed.startIndex)..<closeBracket])
    let rest = String(trimmed[trimmed.index(after: closeBracket)...]).trimmingCharacters(in: .whitespaces)

    guard let spaceAfterLevel = rest.firstIndex(of: " ") else { continue }
    let level = String(rest[rest.startIndex..<spaceAfterLevel])

    let afterLevel = String(rest[rest.index(after: spaceAfterLevel)...])

    guard let openParen = afterLevel.firstIndex(of: "("),
          let closeParen = afterLevel.firstIndex(of: ")") else { continue }

    let component = String(afterLevel[afterLevel.index(after: openParen)..<closeParen])

    let afterComponent = String(afterLevel[afterLevel.index(after: closeParen)...]).trimmingCharacters(in: .whitespaces)

    guard afterComponent.hasPrefix("- ") else { continue }

    let message = String(afterComponent.dropFirst(2))

    let timePart = timestamp.split(separator: " ").last
    let hourStr = timePart?.split(separator: ":").first
    let hour = Int(hourStr ?? "") ?? 0

    levelCounts[level, default: 0] += 1
    hourCounts[hour, default: 0] += 1

    if level == "ERROR" {
        componentErrors[component, default: 0] += 1
        errorMessages.insert(message)
    }
}

print("=== Log Analysis ===")
print("")
print("Entries by Level:")
for (level, count) in levelCounts.sorted(by: { $0.key < $1.key }) {
    print("  \(level): \(count)")
}
print("")

if let (comp, errCount) = componentErrors.max(by: { $0.value < $1.value }) {
    print("Component with Most Errors: \(comp) (\(errCount) errors)")
} else {
    print("Component with Most Errors: N/A (0 errors)")
}
print("")

print("Unique Error Messages:")
for msg in errorMessages.sorted() {
    print("  - \(msg)")
}
print("")

if let (hour, count) = hourCounts.max(by: { $0.value < $1.value }) {
    print("Busiest Hour: \(String(format: "%02d:00", hour)) (\(count) entries)")
} else {
    print("Busiest Hour: N/A (0 entries)")
}

