import * as fs from 'fs';

const csvPath = '<tmp>';
const content = fs.readFileSync(csvPath, 'utf-8');
const lines = content.trim().split('\n');

function parseCsvLine(line: string): string[] {
  const result: string[] = [];
  let current = '';
  let inQuotes = false;
  for (let i = 0; i < line.length; i++) {
    const ch = line[i];
    if (inQuotes) {
      if (ch === '"') {
        if (i + 1 < line.length && line[i + 1] === '"') {
          current += '"';
          i++;
        } else {
          inQuotes = false;
        }
      } else {
        current += ch;
      }
    } else {
      if (ch === '"') {
        inQuotes = true;
      } else if (ch === ',') {
        result.push(current.trim());
        current = '';
      } else {
        current += ch;
      }
    }
  }
  result.push(current.trim());
  return result;
}

const headers = parseCsvLine(lines[0]);
const colIdx: Record<string, number> = {};
headers.forEach((h, i) => { colIdx[h] = i; });

interface Employee {
  name: string;
  department: string;
  salary: number;
}

const employees: Employee[] = [];
for (let i = 1; i < lines.length; i++) {
  const cols = parseCsvLine(lines[i]);
  if (cols.length < 6) continue;
  employees.push({
    name: cols[colIdx['name']],
    department: cols[colIdx['department']],
    salary: parseFloat(cols[colIdx['salary']])
  });
}

function formatNumber(n: number, decimals: number): string {
  let negative = n < 0;
  let abs = Math.abs(n);
  let fixed = abs.toFixed(decimals);
  let [intStr, decStr] = fixed.split('.');
  let formatted = intStr.replace(/\B(?=(\d{3})+(?!\d))/g, ',');
  let result = (negative ? '-' : '') + formatted;
  if (decimals > 0 && decStr !== undefined) {
    result += '.' + decStr;
  }
  return result;
}

const deptSalaries: Map<string, number[]> = new Map();
for (const emp of employees) {
  if (!deptSalaries.has(emp.department)) {
    deptSalaries.set(emp.department, []);
  }
  deptSalaries.get(emp.department)!.push(emp.salary);
}

const sortedDepts = Array.from(deptSalaries.keys()).sort((a, b) => a.localeCompare(b));

let highestPaid = employees[0];
for (const emp of employees) {
  if (emp.salary > highestPaid.salary) {
    highestPaid = emp;
  }
}

const deptCounts: Map<string, number> = new Map();
for (const emp of employees) {
  deptCounts.set(emp.department, (deptCounts.get(emp.department) || 0) + 1);
}

const deptsWithMoreThan2 = Array.from(deptCounts.entries())
  .filter(([, count]) => count > 2)
