        StringBuilder sb = new StringBuilder();
        String line;
        while ((line = reader.readLine()) != null) {
            sb.append(line);
        }
        reader.close();
        conn.disconnect();

        String json = sb.toString();

        JsonParser parser = new JsonParser(json);
        Object root = parser.parse();

        @SuppressWarnings("unchecked")
        List<Map<String, Object>> products = (List<Map<String, Object>>) root;

        List<Map<String, Object>> filtered = products.stream()
                .filter(p -> ((Number) p.get("price")).doubleValue() > 50.00)
                .sorted(Comparator.comparing(p -> (String) p.get("name")))
                .collect(Collectors.toList());

        System.out.println("=== Filtered Products (price > $50.00) ===");
        System.out.println();
