import * as fs from "fs";

interface Edge {
    from: string;
    to: string;
    weight: number;
}

interface Graph {
    nodes: string[];
    edges: Edge[];
}

function main(): void {
    const filePath = "<tmp>";
    const data: string = fs.readFileSync(filePath, "utf-8");
    const graph: Graph = JSON.parse(data);

    const adj: Map<string, { to: string; weight: number }[]> = new Map();
    for (const node of graph.nodes) {
        adj.set(node, []);
    }
    for (const edge of graph.edges) {
        adj.get(edge.from)!.push({ to: edge.to, weight: edge.weight });
        adj.get(edge.to)!.push({ to: edge.from, weight: edge.weight });
    }

    const source = "A";
    const dist: Map<string, number> = new Map();
    const visited: Set<string> = new Set();

    for (const node of graph.nodes) {
        dist.set(node, Infinity);
    }
    dist.set(source, 0);

    for (let i = 0; i < graph.nodes.length; i++) {
        let u: string | null = null;
        let minDist: number = Infinity;
        for (const node of graph.nodes) {
            if (!visited.has(node) && dist.get(node)! < minDist) {
                minDist = dist.get(node)!;
                u = node;
            }
        }

        if (u === null || minDist === Infinity) {
            break;
        }

        visited.add(u);

        const neighbors = adj.get(u)!;
        for (const { to, weight } of neighbors) {
            if (!visited.has(to)) {
                const newDist = dist.get(u)! + weight;
                if (newDist < dist.get(to)!) {
                    dist.set(to, newDist);
                }
            }
        }
    }

    const sortedNodes: string[] = [...graph.nodes].sort();
    process.stdout.write("=== Shortest Paths from A ===\n");
    process.stdout.write("\n");
    for (const node of sortedNodes) {
        const d: number = dist.get(node)!;
        const display: string = d === Infinity ? "unreachable" : String(d);
        process.stdout.write(`A -> ${node}: ${display}\n`);
    }
}

main();

