public class Main {

    static class JsonParser {
        private String input;
        private int pos;

        public JsonParser(String input) {
            this.input = input;
            this.pos = 0;
        }

        public Object parse() {
            skipWhitespace();
            Object result = parseValue();
            skipWhitespace();
            if (pos < input.length()) throw new RuntimeException("Trailing characters at pos " + pos);
            return result;
        }

        private void skipWhitespace() {
            while (pos < input.length() && Character.isWhitespace(input.charAt(pos))) pos++;
        }

        private Object parseValue() {
            skipWhitespace();
            if (pos >= input.length()) throw new RuntimeException("Unexpected end of input");
            char c = input.charAt(pos);
            if (c == '{') return parseObject();
            if (c == '[') return parseArray();
            if (c == '"') return parseString();
            if (c == 't') return parseLiteral("true", Boolean.TRUE);
            if (c == 'f') return parseLiteral("false", Boolean.FALSE);
            if (c == 'n') return parseLiteral("null", null);
            if (c == '-' || (c >= '0' && c <= '9')) return parseNumber();
            throw new RuntimeException("Unexpected character: " + c + " at pos " + pos);
        }

        @SuppressWarnings("unchecked")
        private Map<String, Object> parseObject() {
            Map<String, Object> map = new LinkedHashMap<>();
            pos++;
            skipWhitespace();
            if (pos < input.length() && input.charAt(pos) == '}') {
                pos++;
                return map;
            }
            while (true) {
                skipWhitespace();
                String key = parseString();
                skipWhitespace();
                if (pos >= input.length() || input.charAt(pos) != ':') throw new RuntimeException("Expected ':' at pos " + pos);
                pos++;
                skipWhitespace();
                Object value = parseValue();
                map.put(key, value);
                skipWhitespace();
                if (pos >= input.length()) throw new RuntimeException("Unexpected end in object");
                if (input.charAt(pos) == ',') {
                    pos++;
                } else if (input.charAt(pos) == '}') {
                    pos++;
                    break;
                } else {
                    throw new RuntimeException("Expected ',' or '}' at pos " + pos);
                }
            }
            return map;
        }

        private List<Object> parseArray() {
            List<Object> list = new ArrayList<>();
            pos++;
            skipWhitespace();
            if (pos < input.length() && input.charAt(pos) == ']') {
                pos++;
                return list;
            }
            while (true) {
                skipWhitespace();
                Object value = parseValue();
                list.add(value);
                skipWhitespace();
                if (pos >= input.length()) throw new RuntimeException("Unexpected end in array");
                if (input.charAt(pos) == ',') {
                    pos++;
                } else if (input.charAt(pos) == ']') {
