static char *dup_str(const char *s) {
    size_t len = strlen(s) + 1;
    char *p = malloc(len);
    if (p) memcpy(p, s, len);
    return p;
}

static void format_commas(long long n, char *buf, size_t bufsize) {
    char digits[32];
    int neg = 0;
    if (n < 0) { neg = 1; n = -n; }
    int len = snprintf(digits, sizeof(digits), "%lld", n);
    int pos = 0;
    if (neg) buf[pos++] = '-';
    for (int i = 0; i < len; i++) {
        buf[pos++] = digits[i];
        int remaining = len - i - 1;
        if (remaining > 0 && remaining % 3 == 0) {
            buf[pos++] = ',';
        }
    }
    buf[pos] = '\0';
}

static void format_money_2dp(double val, char *buf, size_t bufsize) {
    long long cents;
    if (val >= 0.0) {
        cents = (long long)(val * 100.0 + 0.5);
    } else {
        cents = -(long long)((-val) * 100.0 + 0.5);
    }
    long long whole = cents / 100;
    int frac = (int)(cents % 100);
    if (frac < 0) frac = -frac;
    char whole_str[64];
    format_commas(whole, whole_str, sizeof(whole_str));
    snprintf(buf, bufsize, "%s.%02d", whole_str, frac);
}

