public class Main {
    static class FileStats {
        String path;
        long lines;
        long chars;
        FileStats(String path, long lines, long chars) {
            this.path = path;
            this.lines = lines;
            this.chars = chars;
        }
    }

    public static void main(String[] args) throws Exception {
        Path root = Paths.get("<tmp>");

        Map<String, List<FileStats>> extMap = new TreeMap<>();

        if (!Files.exists(root)) {
            System.out.print("=== File Tree Analysis ===\n\nTotal: 0 files, 0 lines, 0 characters\n");
            return;
        }

        Files.walkFileTree(root, EnumSet.noneOf(FileVisitOption.FOLLOW_LINKS), Integer.MAX_VALUE,
            new SimpleFileVisitor<Path>() {
                @Override
                public FileVisitResult visitFile(Path file, BasicFileAttributes attrs) {
                    if (attrs.isSymbolicLink()) return FileVisitResult.CONTINUE;
                    if (!attrs.isRegularFile()) return FileVisitResult.CONTINUE;

                    String relPath = root.relativize(file).toString().replace('\\', '/');

                    String fileName = file.getFileName().toString();
                    String ext = "";
                    int lastDot = fileName.lastIndexOf('.');
                    if (lastDot > 0) {
                        ext = fileName.substring(lastDot);
                    }

                    long bytes = attrs.size();
                    long lines = countLines(file);

                    extMap.computeIfAbsent(ext, k -> new ArrayList<>()).add(new FileStats(relPath, lines, bytes));
                    return FileVisitResult.CONTINUE;
                }
            });

        for (List<FileStats> list : extMap.values()) {
            list.sort(Comparator.comparing(f -> f.path));
        }

        StringBuilder sb = new StringBuilder();
        sb.append("=== File Tree Analysis ===\n");
        sb.append("\n");

        int totalFiles = 0;
        long totalLines = 0;
        long totalChars = 0;

        for (Map.Entry<String, List<FileStats>> entry : extMap.entrySet()) {
            String ext = entry.getKey();
            List<FileStats> files = entry.getValue();

            long extLines = 0;
            long extChars = 0;
            for (FileStats fs : files) {
                extLines += fs.lines;
                extChars += fs.chars;
            }

            sb.append("Extension: ").append(ext).append("\n");
            sb.append("  Files: ").append(files.size()).append("\n");
            sb.append("  Total Lines: ").append(extLines).append("\n");
            sb.append("  Total Characters: ").append(extChars).append("\n");

            for (FileStats fs : files) {
                sb.append("    ").append(fs.path).append(": ").append(fs.lines).append(" lines, ").append(fs.chars).append(" chars\n");
            }

            totalFiles += files.size();
            totalLines += extLines;
            totalChars += extChars;
        }

        sb.append("\n");
        sb.append("Total: ").append(totalFiles).append(" files, ").append(totalLines).append(" lines, ").append(totalChars).append(" characters\n");

        System.out.print(sb.toString());
    }

    static long countLines(Path file) {
        try (BufferedReader reader = Files.newBufferedReader(file)) {
            long count = 0;
            while (reader.readLine() != null) {
                count++;
            }
            return count;
        } catch (IOException e) {
            return 0;
        }
    }
