  let lines = 0;
  for (let i = 0; i < buffer.length; i++) {
    if (buffer[i] === 10) lines++;
  }
  if (buffer[buffer.length - 1] !== 10) lines++;
  return lines;
}

function walkDir(dir: string, root: string): FileEntry[] {
  const results: FileEntry[] = [];
  let entries: fs.Dirent[];
  try {
    entries = fs.readdirSync(dir, { withFileTypes: true });
  } catch {
    return results;
  }

  for (const entry of entries) {
    if (entry.isSymbolicLink()) continue;

    const fullPath = path.join(dir, entry.name);
    const relativePath = path.relative(root, fullPath).split(path.sep).join('/');

    if (entry.isDirectory()) {
      results.push(...walkDir(fullPath, root));
    } else if (entry.isFile()) {
      try {
        const buffer = fs.readFileSync(fullPath);
        const lines = countLines(buffer);
        const chars = buffer.length;
        results.push({ relativePath, lines, chars });
      } catch {
        // skip unreadable files
