use std::collections::BTreeMap;
use std::fs;

#[derive(Debug, Clone, PartialEq)]
enum JsonValue {
    Null,
    Bool(bool),
    Number(f64),
    Str(String),
    Array(Vec<JsonValue>),
    Object(BTreeMap<String, JsonValue>),
}

struct Parser {
    chars: Vec<char>,
    pos: usize,
}

impl Parser {
    fn new(s: &str) -> Self {
        Parser { chars: s.chars().collect(), pos: 0 }
    }

    fn skip_whitespace(&mut self) {
        while self.pos < self.chars.len() && self.chars[self.pos].is_whitespace() {
            self.pos += 1;
        }
    }

    fn peek(&self) -> Option<char> {
        self.chars.get(self.pos).copied()
    }

    fn next(&mut self) -> Option<char> {
        let c = self.peek();
        if c.is_some() {
            self.pos += 1;
        }
        c
    }

    fn expect(&mut self, c: char) {
        self.skip_whitespace();
        assert_eq!(self.next(), Some(c), "Expected '{}'", c);
    }

    fn parse_value(&mut self) -> JsonValue {
        self.skip_whitespace();
        match self.peek() {
            Some('{') => self.parse_object(),
            Some('[') => self.parse_array(),
            Some('"') => JsonValue::Str(self.parse_string()),
            Some('t') => { self.parse_literal("true"); JsonValue::Bool(true) }
            Some('f') => { self.parse_literal("false"); JsonValue::Bool(false) }
            Some('n') => { self.parse_literal("null"); JsonValue::Null }
            _ => self.parse_number(),
        }
    }

    fn parse_literal(&mut self, lit: &str) {
        for c in lit.chars() {
            assert_eq!(self.next(), Some(c), "Bad literal");
        }
    }

    fn parse_string(&mut self) -> String {
        self.expect('"');
        let mut s = String::new();
        loop {
            match self.next() {
                Some('"') => break,
                Some('\\') => {
                    match self.next() {
                        Some('"') => s.push('"'),
                        Some('\\') => s.push('\\'),
                        Some('/') => s.push('/'),
                        Some('b') => s.push('\u{0008}'),
                        Some('f') => s.push('\u{000C}'),
                        Some('n') => s.push('\n'),
                        Some('r') => s.push('\r'),
                        Some('t') => s.push('\t'),
                        Some('u') => {
                            let mut code = 0u32;
                            for _ in 0..4 {
                                let c = self.next().unwrap();
                                code = code * 16 + (c as u32).to_digit(16).unwrap();
                            }
                            if (0xD800..=0xDBFF).contains(&code) {
                                if self.peek() == Some('\\') {
                                    self.next();
                                    if self.peek() == Some('u') {
                                        self.next();
                                        let mut low = 0u32;
                                        for _ in 0..4 {
                                            let c = self.next().unwrap();
                                            low = low * 16 + (c as u32).to_digit(16).unwrap();
                                        }
                                        let cp = 0x10000 + ((code - 0xD800) << 10) + (low - 0xDC00);
                                        s.push(char::from_u32(cp).unwrap_or('\u{FFFD}'));
                                    } else {
                                        s.push('\u{FFFD}');
                                    }
                                } else {
                                    s.push('\u{FFFD}');
                                }
                            } else {
                                s.push(char::from_u32(code).unwrap_or('\u{FFFD}'));
                            }
                        }
                        _ => {}
                    }
                }
                Some(c) => s.push(c),
                None => break,
            }
        }
        s
    }

    fn parse_number(&mut self) -> JsonValue {
        self.skip_whitespace();
        let start = self.pos;
        if self.peek() == Some('-') {
            self.pos += 1;
        }
        while self.pos < self.chars.len() && self.chars[self.pos].is_ascii_digit() {
            self.pos += 1;
        }
        if self.peek() == Some('.') {
            self.pos += 1;
            while self.pos < self.chars.len() && self.chars[self.pos].is_ascii_digit() {
                self.pos += 1;
            }
        }
        if self.peek() == Some('e') || self.peek() == Some('E') {
            self.pos += 1;
            if self.peek() == Some('+') || self.peek() == Some('-') {
                self.pos += 1;
            }
            while self.pos < self.chars.len() && self.chars[self.pos].is_ascii_digit() {
                self.pos += 1;
            }
        }
        let num_str: String = self.chars[start..self.pos].iter().collect();
        JsonValue::Number(num_str.parse::<f64>().unwrap())
    }

    fn parse_array(&mut self) -> JsonValue {
        self.expect('[');
        let mut arr = Vec::new();
        self.skip_whitespace();
        if self.peek() == Some(']') {
            self.next();
            return JsonValue::Array(arr);
        }
        loop {
            arr.push(self.parse_value());
            self.skip_whitespace();
            match self.next() {
                Some(',') => continue,
                Some(']') => break,
                _ => panic!("Expected ',' or ']' in array"),
            }
        }
        JsonValue::Array(arr)
    }

    fn parse_object(&mut self) -> JsonValue {
        self.expect('{');
        let mut obj = BTreeMap::new();
        self.skip_whitespace();
        if self.peek() == Some('}') {
            self.next();
            return JsonValue::Object(obj);
        }
        loop {
            self.skip_whitespace();
            let key = self.parse_string();
            self.expect(':');
            let val = self.parse_value();
            obj.insert(key, val);
            self.skip_whitespace();
            match self.next() {
                Some(',') => continue,
                Some('}') => break,
                _ => panic!("Expected ',' or '}}' in object"),
            }
        }
        JsonValue::Object(obj)
    }
}

fn parse_json(s: &str) -> JsonValue {
    let mut parser = Parser::new(s);
    parser.parse_value()
}

fn deep_merge(a: JsonValue, b: JsonValue) -> JsonValue {
    match (&a, &b) {
        (JsonValue::Object(a_obj), JsonValue::Object(b_obj)) => {
            let mut merged = a_obj.clone();
            for (key, b_val) in b_obj {
                if let Some(a_val) = merged.get(key) {
                    merged.insert(key.clone(), deep_merge(a_val.clone(), b_val.clone()));
                } else {
                    merged.insert(key.clone(), b_val.clone());
                }
            }
            JsonValue::Object(merged)
        }
        (JsonValue::Array(a_arr), JsonValue::Array(b_arr)) => {
            let mut result = a_arr.clone();
            for item in b_arr {
                if !result.contains(item) {
                    result.push(item.clone());
                }
            }
            JsonValue::Array(result)
        }
        _ => b,
    }
}

fn escape_string(s: &str) -> String {
    let mut result = String::new();
    for c in s.chars() {
        match c {
            '"' => result.push_str("\\\""),
            '\\' => result.push_str("\\\\"),
            '\n' => result.push_str("\\n"),
            '\r' => result.push_str("\\r"),
            '\t' => result.push_str("\\t"),
            '\u{0008}' => result.push_str("\\b"),
            '\u{000C}' => result.push_str("\\f"),
            c if (c as u32) < 0x20 => {
                result.push_str(&format!("\\u{:04x}", c as u32));
            }
            c => result.push(c),
        }
    }
    result
}

fn format_number(n: f64) -> String {
    if n.fract() == 0.0 && n.abs() < 1e15 {
        format!("{}", n as i64)
    } else {
        format!("{}", n)
    }
}

fn serialize(value: &JsonValue, indent: usize) -> String {
    let pad = "  ".repeat(indent);
    let inner_pad = "  ".repeat(indent + 1);
    match value {
        JsonValue::Null => "null".to_string(),
        JsonValue::Bool(b) => b.to_string(),
        JsonValue::Number(n) => format_number(*n),
        JsonValue::Str(s) => format!("\"{}\"", escape_string(s)),
        JsonValue::Array(arr) => {
            if arr.is_empty() {
                return "[]".to_string();
            }
            let mut parts = Vec::new();
            for item in arr {
                parts.push(format!("{}{}", inner_pad, serialize(item, indent + 1)));
            }
            format!("[\n{}\n{}]", parts.join(",\n"), pad)
        }
        JsonValue::Object(obj) => {
            if obj.is_empty() {
                return "{}".to_string();
            }
            let mut parts = Vec::new();
            for (key, val) in obj {
                parts.push(format!(
                    "{}\"{}\": {}",
                    inner_pad,
                    escape_string(key),
                    serialize(val, indent + 1)
                ));
            }
            format!("{{\n{}\n{}}}", parts.join(",\n"), pad)
        }
    }
}

fn main() {
    let path_a = "<tmp>";
    let path_b = "<tmp>";

    let content_a = fs::read_to_string(path_a).expect("Failed to read config_a.json");
    let content_b = fs::read_to_string(path_b).expect("Failed to read config_b.json");

    let a = parse_json(&content_a);
    let b = parse_json(&content_b);

    let merged = deep_merge(a, b);

    println!("{}", serialize(&merged, 0));
}

