        self.s.get(self.pos).copied()
    }

    fn expect(&mut self, c: u8) {
        self.skip_ws();
        if self.peek() == Some(c) {
            self.pos += 1;
        } else {
            panic!("Expected '{}' at pos {}", c as char, self.pos);
        }
    }

    fn parse_value(&mut self) -> Json {
        self.skip_ws();
        match self.peek() {
            Some(b'{') => self.parse_object(),
            Some(b'[') => self.parse_array(),
            Some(b'"') => Json::Str(self.parse_string()),
            Some(b't') => { self.pos += 4; Json::Bool(true) }
            Some(b'f') => { self.pos += 5; Json::Bool(false) }
            Some(b'n') => { self.pos += 4; Json::Null }
            _ => Json::Num(self.parse_number()),
        }
    }

    fn parse_string(&mut self) -> String {
        self.expect(b'"');
        let mut result = String::new();
        loop {
            let c = self.s[self.pos] as char;
            self.pos += 1;
            if c == '"' { break; }
            if c == '\\' {
                let esc = self.s[self.pos] as char;
                self.pos += 1;
                match esc {
                    '"' => result.push('"'),
                    '\\' => result.push('\\'),
                    '/' => result.push('/'),
                    'n' => result.push('\n'),
                    't' => result.push('\t'),
                    'r' => result.push('\r'),
                    'b' => result.push('\u{0008}'),
                    'f' => result.push('\u{000C}'),
                    'u' => {
                        let mut code = 0u32;
                        for _ in 0..4 {
                            let h = (self.s[self.pos] as char).to_digit(16).unwrap() as u32;
                            code = code * 16 + h;
                            self.pos += 1;
                        }
                        result.push(char::from_u32(code).unwrap_or('\u{FFFD}'));
                    }
                    _ => result.push(esc),
                }
            } else {
                result.push(c);
            }
        }
        result
    }

    fn parse_number(&mut self) -> f64 {
        self.skip_ws();
        let start = self.pos;
        if self.peek() == Some(b'-') { self.pos += 1; }
        while self.pos < self.s.len() {
            let c = self.s[self.pos] as char;
            if c.is_ascii_digit() || c == '.' || c == '-' || c == '+' || c == 'e' || c == 'E' {
                self.pos += 1;
            } else {
                break;
            }
        }
        std::str::from_utf8(&self.s[start..self.pos]).unwrap().parse().unwrap()
    }

    fn parse_array(&mut self) -> Json {
        self.expect(b'[');
        let mut items = Vec::new();
        self.skip_ws();
        if self.peek() == Some(b']') {
            self.pos += 1;
            return Json::Array(items);
        }
        loop {
            items.push(self.parse_value());
            self.skip_ws();
            if self.peek() == Some(b',') {
                self.pos += 1;
            } else {
                break;
            }
        }
        self.expect(b']');
        Json::Array(items)
    }

    fn parse_object(&mut self) -> Json {
        self.expect(b'{');
        let mut items = Vec::new();
        self.skip_ws();
        if self.peek() == Some(b'}') {
            self.pos += 1;
            return Json::Object(items);
        }
        loop {
            self.skip_ws();
            let key = self.parse_string();
            self.expect(b':');
            let val = self.parse_value();
            items.push((key, val));
            self.skip_ws();
            if self.peek() == Some(b',') {
                self.pos += 1;
            } else {
                break;
            }
        }
        self.expect(b'}');
        Json::Object(items)
    }
}

fn get_obj_field<'a>(obj: &'a [(String, Json)], key: &str) -> &'a Json {
    for (k, v) in obj {
        if k == key {
            return v;
        }
    }
    panic!("Missing field: {}", key);
}

fn main() {
    let content = fs::read_to_string("<tmp>")
        .expect("Failed to read graph.json");

    let mut parser = Parser::new(&content);
    let json = parser.parse_value();

    let (nodes, edges) = match &json {
        Json::Object(obj) => {
            let nodes_json = get_obj_field(obj, "nodes");
            let edges_json = get_obj_field(obj, "edges");

            let nodes: Vec<String> = match nodes_json {
                Json::Array(arr) => arr.iter().map(|v| match v {
                    Json::Str(s) => s.clone(),
                    _ => panic!("Expected string in nodes"),
                }).collect(),
                _ => panic!("Expected array for nodes"),
            };

            let edges: Vec<(String, String, i64)> = match edges_json {
                Json::Array(arr) => arr.iter().map(|v| {
                    match v {
                        Json::Object(eobj) => {
                            let from = match get_obj_field(eobj, "from") {
                                Json::Str(s) => s.clone(),
                                _ => panic!("Expected string for from"),
                            };
                            let to = match get_obj_field(eobj, "to") {
                                Json::Str(s) => s.clone(),
                                _ => panic!("Expected string for to"),
                            };
                            let weight = match get_obj_field(eobj, "weight") {
                                Json::Num(n) => *n as i64,
                                _ => panic!("Expected number for weight"),
                            };
                            (from, to, weight)
                        }
                        _ => panic!("Expected object in edges"),
                    }
                }).collect(),
                _ => panic!("Expected array for edges"),
            };

            (nodes, edges)
        }
        _ => panic!("Expected JSON object"),
    };

    // Build adjacency list (undirected)
    let mut adj: HashMap<String, Vec<(String, i64)>> = HashMap::new();
    for node in &nodes {
        adj.entry(node.clone()).or_insert_with(Vec::new);
    }
    for (from, to, weight) in &edges {
        adj.entry(from.clone()).or_insert_with(Vec::new).push((to.clone(), *weight));
        adj.entry(to.clone()).or_insert_with(Vec::new).push((from.clone(), *weight));
    }

    // Dijkstra's algorithm
    let start = "A".to_string();
    let dist = dijkstra(&adj, &start);

    // Output
    println!("=== Shortest Paths from A ===");
    println!();
    let mut sorted_nodes: Vec<&String> = nodes.iter().collect();
    sorted_nodes.sort();
    for node in &sorted_nodes {
        let d = *dist.get(*node).unwrap_or(&i64::MAX);
        if d == i64::MAX {
            println!("A -> {}: unreachable", node);
        } else {
            println!("A -> {}: {}", node, d);
        }
    }
}

fn dijkstra(adj: &HashMap<String, Vec<(String, i64)>>, start: &str) -> HashMap<String, i64> {
    let mut dist: HashMap<String, i64> = HashMap::new();
    for node in adj.keys() {
        dist.insert(node.clone(), i64::MAX);
    }
    dist.insert(start.to_string(), 0);

    // Min-heap of (distance, node)
    let mut heap: BinaryHeap<Reverse<(i64, String)>> = BinaryHeap::new();
    heap.push(Reverse((0, start.to_string())));

    while let Some(Reverse((d, node))) = heap.pop() {
        if d > dist.get(&node).copied().unwrap_or(i64::MAX) {
            continue;
        }
        if let Some(neighbors) = adj.get(&node) {
            for (neighbor, weight) in neighbors {
                let new_dist = d + weight;
                let current = dist.get(neighbor).copied().unwrap_or(i64::MAX);
                if new_dist < current {
                    dist.insert(neighbor.clone(), new_dist);
                    heap.push(Reverse((new_dist, neighbor.clone())));
                }
            }
        }
    }

    dist
}
