const B: number[][] = [[9, 8, 7], [6, 5, 4], [3, 2, 1]];

function multiply(A: number[][], B: number[][]): number[][] {
    const rows = A.length;
    const inner = A[0].length;
    const cols = B[0].length;
    const C: number[][] = Array.from({ length: rows }, () => Array<number>(cols).fill(0));
    for (let i = 0; i < rows; i++) {
        for (let j = 0; j < cols; j++) {
            for (let k = 0; k < inner; k++) {
                C[i][j] += A[i][k] * B[k][j];
            }
        }
    }
    return C;
}

function determinant(M: number[][]): number {
    const n = M.length;
    if (n === 1) return M[0][0];
    if (n === 2) return M[0][0] * M[1][1] - M[0][1] * M[1][0];
    let det = 0;
    for (let j = 0; j < n; j++) {
        const minor: number[][] = [];
        for (let i = 1; i < n; i++) {
            minor.push(M[i].filter((_, idx) => idx !== j));
        }
        const sign = j % 2 === 0 ? 1 : -1;
        det += sign * M[0][j] * determinant(minor);
    }
    return det;
}

function formatMatrix(M: number[][]): string {
    return M.map(row => "  " + row.map(v => v.toString().padStart(4)).join(" ")).join("\n");
}

