import Foundation

func multiply(_ A: [[Int]], _ B: [[Int]]) -> [[Int]] {
    let rows = A.count
    let cols = B[0].count
    let inner = B.count
    var C = Array(repeating: Array(repeating: 0, count: cols), count: rows)
    for i in 0..<rows {
        for j in 0..<cols {
            var sum = 0
            for k in 0..<inner {
                sum += A[i][k] * B[k][j]
            }
            C[i][j] = sum
        }
    }
    return C
}

func determinant(_ M: [[Int]]) -> Int {
    let n = M.count
    if n == 1 { return M[0][0] }
    if n == 2 { return M[0][0] * M[1][1] - M[0][1] * M[1][0] }
    var det = 0
    for j in 0..<n {
        var minor = [[Int]]()
        for i in 1..<n {
            var row = [Int]()
            for k in 0..<n where k != j {
                row.append(M[i][k])
            }
            minor.append(row)
        }
        let sign = (j % 2 == 0) ? 1 : -1
        det += sign * M[0][j] * determinant(minor)
    }
    return det
}

func printMatrix(_ M: [[Int]]) {
    for row in M {
        var line = "  "
        for (i, v) in row.enumerated() {
            if i > 0 { line += " " }
            line += String(format: "%4d", v)
        }
        print(line)
    }
}

