import Foundation

let baseDir = "<tmp>"
let fm = FileManager.default

struct FileStat {
    let relativePath: String
    let lines: Int
    let chars: Int
}

var groups: [String: [FileStat]] = [:]
var visited: Set<String> = []

let baseURL = URL(fileURLWithPath: baseDir)
let enumerator = fm.enumerator(at: baseURL,
                                includingPropertiesForKeys: [.isRegularFileKey, .isSymbolicLinkKey],
                                options: [],
                                errorHandler: nil)

while let url = enumerator.nextObject() as? URL {
    let values = try? url.resourceValues(forKeys: [.isRegularFileKey, .isSymbolicLinkKey])
    let isSymlink = values?.isSymbolicLink ?? false
    let isRegular = values?.isRegularFile ?? false

    if isSymlink { continue }
    if !isRegular { continue }

    let fullPath = url.path
    if visited.contains(fullPath) { continue }
    visited.insert(fullPath)

    let relativePath = String(fullPath.dropFirst(baseDir.count + 1))

    guard let data = try? Data(contentsOf: url) else { continue }
    let charCount = data.count

    let lines: Int
    if data.isEmpty {
        lines = 0
    } else {
        var newlineCount = 0
        for byte in data {
            if byte == 10 { newlineCount += 1 }
        }
        let endsWithNewline = data[data.count - 1] == 10
        lines = endsWithNewline ? newlineCount : newlineCount + 1
    }

    let ext = url.pathExtension
    let extKey = ext.isEmpty ? "" : "." + ext

    groups[extKey, default: []].append(FileStat(relativePath: relativePath, lines: lines, chars: charCount))
}

print("=== File Tree Analysis ===")
print("")

var totalFiles = 0
var totalLines = 0
var totalChars = 0

let sortedExts = groups.keys.sorted()

for ext in sortedExts {
    let fileStats = groups[ext]!.sorted { $0.relativePath < $1.relativePath }
    let fileCount = fileStats.count
    let extLines = fileStats.reduce(0) { $0 + $1.lines }
    let extChars = fileStats.reduce(0) { $0 + $1.chars }

    print("Extension: \(ext)")
    print("  Files: \(fileCount)")
    print("  Total Lines: \(extLines)")
    print("  Total Characters: \(extChars)")
    for f in fileStats {
        print("    \(f.relativePath): \(f.lines) lines, \(f.chars) chars")
    }

    totalFiles += fileCount
    totalLines += extLines
    totalChars += extChars
}

print("")
print("Total: \(totalFiles) files, \(totalLines) lines, \(totalChars) characters")

