    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            int sum = 0;
            for (int k = 0; k < N; k++) {
                sum += a[i * N + k] * b[k * N + j];
            }
            c[i * N + j] = sum;
        }
    }
}

long det(int *m, int n) {
    if (n == 1) return m[0];
    if (n == 2) return (long)m[0] * m[3] - (long)m[1] * m[2];

    long result = 0;
    int *minor = malloc((size_t)(n - 1) * (n - 1) * sizeof(int));
    for (int j = 0; j < n; j++) {
        int sign = (j % 2 == 0) ? 1 : -1;
        int idx = 0;
        for (int i = 1; i < n; i++) {
            for (int k = 0; k < n; k++) {
                if (k == j) continue;
                minor[idx++] = m[i * n + k];
            }
        }
        result += sign * (long)m[j] * det(minor, n - 1);
    }
    free(minor);
    return result;
}

