#define BASE_DIR "<tmp>"
#define READ_BUF 65536

typedef struct {
    char *rel_path;
    char *ext;
    long lines;
    long chars;
} FileInfo;

static FileInfo *files = NULL;
static int nfiles = 0;
static int files_cap = 0;

static void add_file(const char *rel_path, const char *ext, long lines, long chars) {
    if (nfiles >= files_cap) {
        files_cap = files_cap ? files_cap * 2 : 128;
        files = realloc(files, (size_t)files_cap * sizeof(FileInfo));
        if (!files) { fprintf(stderr, "OOM\n"); exit(1); }
    }
    files[nfiles].rel_path = strdup(rel_path);
    files[nfiles].ext = strdup(ext);
    files[nfiles].lines = lines;
    files[nfiles].chars = chars;
    nfiles++;
}

static long count_lines(const char *path) {
    FILE *f = fopen(path, "rb");
    if (!f) return 0;
    long nl = 0;
    int last = -1;
    char *buf = malloc(READ_BUF);
    if (!buf) { fclose(f); return 0; }
    size_t n;
    while ((n = fread(buf, 1, READ_BUF, f)) > 0) {
        for (size_t i = 0; i < n; i++) {
            if (buf[i] == '\n') nl++;
            last = (unsigned char)buf[i];
        }
    }
    free(buf);
    fclose(f);
    if (last == -1) return 0;
    if (last != '\n') nl++;
    return nl;
}

static long get_fsize(const char *path) {
    struct stat st;
    if (stat(path, &st) != 0) return 0;
    return (long)st.st_size;
}

static char *extract_ext(const char *rel_path) {
    const char *slash = strrchr(rel_path, '/');
    const char *fname = slash ? slash + 1 : rel_path;
    const char *dot = strrchr(fname, '.');
    if (dot && dot != fname) {
        return strdup(dot);
    }
    return strdup("");
}

static void walk(const char *full, const char *rel) {
    DIR *d = opendir(full);
    if (!d) return;
    struct dirent *e;
    while ((e = readdir(d)) != NULL) {
        if (strcmp(e->d_name, ".") == 0 || strcmp(e->d_name, "..") == 0)
            continue;

        size_t flen = strlen(full) + 1 + strlen(e->d_name) + 1;
        char *fpath = malloc(flen);
        if (!fpath) { closedir(d); return; }
        snprintf(fpath, flen, "%s/%s", full, e->d_name);

        char *rpath;
        if (rel && rel[0]) {
            size_t rlen = strlen(rel) + 1 + strlen(e->d_name) + 1;
            rpath = malloc(rlen);
            if (!rpath) { free(fpath); closedir(d); return; }
            snprintf(rpath, rlen, "%s/%s", rel, e->d_name);
        } else {
            rpath = strdup(e->d_name);
            if (!rpath) { free(fpath); closedir(d); return; }
        }

        struct stat st;
        if (lstat(fpath, &st) == 0) {
            if (S_ISLNK(st.st_mode)) {
                /* skip symlinks */
            } else if (S_ISDIR(st.st_mode)) {
                walk(fpath, rpath);
            } else if (S_ISREG(st.st_mode)) {
                char *ext = extract_ext(rpath);
                add_file(rpath, ext, count_lines(fpath), get_fsize(fpath));
                free(ext);
            }
        }
        free(fpath);
        free(rpath);
    }
    closedir(d);
}

static int cmp_fileinfo(const void *a, const void *b) {
    const FileInfo *fa = (const FileInfo *)a;
    const FileInfo *fb = (const FileInfo *)b;
    int c = strcmp(fa->ext, fb->ext);
    if (c != 0) return c;
    return strcmp(fa->rel_path, fb->rel_path);
}

int main(void) {
    walk(BASE_DIR, "");

    if (nfiles > 0) {
        qsort(files, (size_t)nfiles, sizeof(FileInfo), cmp_fileinfo);
    }

    printf("=== File Tree Analysis ===\n");
    printf("\n");

    long total_lines = 0, total_chars = 0;

    int i = 0;
    while (i < nfiles) {
        const char *cur_ext = files[i].ext;
        int j = i;
        long g_lines = 0, g_chars = 0;
        int g_count = 0;
        while (j < nfiles && strcmp(files[j].ext, cur_ext) == 0) {
            g_lines += files[j].lines;
            g_chars += files[j].chars;
            g_count++;
            j++;
        }

        printf("Extension: %s\n", cur_ext);
        printf("  Files: %d\n", g_count);
        printf("  Total Lines: %ld\n", g_lines);
        printf("  Total Characters: %ld\n", g_chars);
        for (int k = i; k < j; k++) {
            printf("    %s: %ld lines, %ld chars\n", files[k].rel_path, files[k].lines, files[k].chars);
        }

        total_lines += g_lines;
        total_chars += g_chars;
        i = j;
    }

    printf("\n");
    printf("Total: %d files, %ld lines, %ld characters\n", nfiles, total_lines, total_chars);

    return 0;
}

