            fputs("null", out);
            break;
        case 1:
            fputs(v->bool_val ? "true" : "false", out);
            break;
        case 2:
            print_number(v->number_val, out);
            break;
        case 3:
            print_string_escaped(v->string_val, out);
            break;
        case 4:
            if (v->count == 0) { fputs("[]", out); break; }
            fputc('[', out);
            for (int i = 0; i < v->count; i++) {
                fputc('\n', out);
                for (int s = 0; s < (indent + 1) * 2; s++) fputc(' ', out);
                print_value(v->items[i], indent + 1, out);
                if (i < v->count - 1) fputc(',', out);
            }
            fputc('\n', out);
            for (int s = 0; s < indent * 2; s++) fputc(' ', out);
            fputc(']', out);
            break;
        case 5:
            if (v->count == 0) { fputs("{}", out); break; }
            fputc('{', out);
            for (int i = 0; i < v->count; i++) {
